package com.example;

import net.runelite.api.ItemComposition;

public class ItemRules
{
    private static final String[] BLOCKED_WIELDABLE = {
            "toktz-xil-ul"
    };

    private static final String[] BLOCKED_TARS = {
            "swamp tar",
            "guam tar",
            "marrentill tar",
            "tarromin tar",
            "harralander tar",
            "irit tar"
    };

    public static boolean isAllowedItem(String itemName, ItemComposition comp)
    {
        return isAllowedItem(itemName, comp, false);
    }

    public static boolean isAllowedItem(String itemName, ItemComposition comp, boolean blockImbuedHeart)
    {
        if (itemName == null || itemName.equals("null") || itemName.isEmpty())
        {
            return true;
        }

        String lower = itemName.toLowerCase().trim();

        // Currency and blessings always allowed
        if (Whitelist.isWhitelisted(lower))
        {
            return true;
        }

        // Imbued heart — allowed unless toggle is on
        if (lower.equals("imbued heart"))
        {
            return !blockImbuedHeart;
        }

        // Saturated heart always blocked
        if (lower.equals("saturated heart"))
        {
            return false;
        }

        // Armour sets allowed but NOT potion sets
        if (lower.contains(" set"))
        {
            if (lower.contains("potion") || lower.contains("(4)") ||
                    lower.contains("(3)") || lower.contains("(2)") ||
                    lower.contains("(1)"))
            {
                return false;
            }
            return true;
        }

        // Darts always blocked
        if (Whitelist.isDart(lower))
        {
            return false;
        }

        // Arrows always blocked including poisoned variants
        if (lower.endsWith("arrow") || lower.endsWith("arrows") ||
                lower.endsWith("arrow(p)") || lower.endsWith("arrows(p)") ||
                lower.endsWith("arrow(p+)") || lower.endsWith("arrows(p+)") ||
                lower.endsWith("arrow(p++)") || lower.endsWith("arrows(p++)") ||
                lower.endsWith("arrow (p)") || lower.endsWith("arrows (p)") ||
                lower.endsWith("arrow (p+)") || lower.endsWith("arrows (p+)") ||
                lower.endsWith("arrow (p++)") || lower.endsWith("arrows (p++)"))
        {
            return false;
        }

        // Bolts always blocked including enchanted and poisoned variants
        if (lower.endsWith("bolt") || lower.endsWith("bolts") ||
                lower.endsWith("bolt(e)") || lower.endsWith("bolts(e)") ||
                lower.endsWith("bolt (e)") || lower.endsWith("bolts (e)") ||
                lower.endsWith("bolt(p)") || lower.endsWith("bolts(p)") ||
                lower.endsWith("bolt (p)") || lower.endsWith("bolts (p)") ||
                lower.endsWith("bolt(p+)") || lower.endsWith("bolts(p+)") ||
                lower.endsWith("bolt (p+)") || lower.endsWith("bolts (p+)") ||
                lower.endsWith("bolt(p++)") || lower.endsWith("bolts(p++)") ||
                lower.endsWith("bolt (p++)") || lower.endsWith("bolts (p++)"))
        {
            return false;
        }

        // Javelins always blocked including poisoned variants
        if (lower.endsWith("javelin") || lower.endsWith("javelins") ||
                lower.endsWith("javelin(p)") || lower.endsWith("javelins(p)") ||
                lower.endsWith("javelin(p+)") || lower.endsWith("javelins(p+)") ||
                lower.endsWith("javelin(p++)") || lower.endsWith("javelins(p++)") ||
                lower.endsWith("javelin (p)") || lower.endsWith("javelins (p)") ||
                lower.endsWith("javelin (p+)") || lower.endsWith("javelins (p+)") ||
                lower.endsWith("javelin (p++)") || lower.endsWith("javelins (p++)"))
        {
            return false;
        }

        // Throwing knives blocked
        if (lower.endsWith(" knife") || lower.endsWith(" knife(p)") ||
                lower.endsWith(" knife(p+)") || lower.endsWith(" knife(p++)") ||
                lower.endsWith(" knife (p)") || lower.endsWith(" knife (p+)") ||
                lower.endsWith(" knife (p++)"))
        {
            return false;
        }

        // Thrownaxes blocked
        if (lower.endsWith("thrownaxe"))
        {
            return false;
        }

        // Tars blocked even though they wield
        for (String tar : BLOCKED_TARS)
        {
            if (lower.equals(tar))
            {
                return false;
            }
        }

        // Specific blocked wieldables
        for (String blocked : BLOCKED_WIELDABLE)
        {
            if (lower.equals(blocked))
            {
                return false;
            }
        }

        // Use item composition to check if it's equipment
        if (comp != null)
        {
            return isEquipmentByComposition(comp);
        }

        return false;
    }

    public static boolean isAllowedItem(String itemName)
    {
        if (itemName == null || itemName.equals("null") || itemName.isEmpty())
        {
            return true;
        }

        String lower = itemName.toLowerCase().trim();

        if (Whitelist.isWhitelisted(lower))
        {
            return true;
        }

        if (lower.equals("imbued heart"))
        {
            return true;
        }

        if (lower.equals("saturated heart"))
        {
            return false;
        }

        if (lower.contains(" set"))
        {
            if (lower.contains("potion") || lower.contains("(4)") ||
                    lower.contains("(3)") || lower.contains("(2)") ||
                    lower.contains("(1)"))
            {
                return false;
            }
            return true;
        }

        if (Whitelist.isDart(lower))
        {
            return false;
        }

        if (lower.endsWith("arrow") || lower.endsWith("arrows") ||
                lower.endsWith("arrow(p)") || lower.endsWith("arrows(p)") ||
                lower.endsWith("arrow(p+)") || lower.endsWith("arrows(p+)") ||
                lower.endsWith("arrow(p++)") || lower.endsWith("arrows(p++)") ||
                lower.endsWith("arrow (p)") || lower.endsWith("arrows (p)") ||
                lower.endsWith("arrow (p+)") || lower.endsWith("arrows (p+)") ||
                lower.endsWith("arrow (p++)") || lower.endsWith("arrows (p++)"))
        {
            return false;
        }

        if (lower.endsWith("bolt") || lower.endsWith("bolts") ||
                lower.endsWith("bolt(e)") || lower.endsWith("bolts(e)") ||
                lower.endsWith("bolt (e)") || lower.endsWith("bolts (e)") ||
                lower.endsWith("bolt(p)") || lower.endsWith("bolts(p)") ||
                lower.endsWith("bolt (p)") || lower.endsWith("bolts (p)") ||
                lower.endsWith("bolt(p+)") || lower.endsWith("bolts(p+)") ||
                lower.endsWith("bolt (p+)") || lower.endsWith("bolts (p+)") ||
                lower.endsWith("bolt(p++)") || lower.endsWith("bolts(p++)") ||
                lower.endsWith("bolt (p++)") || lower.endsWith("bolts (p++)"))
        {
            return false;
        }

        if (lower.endsWith("javelin") || lower.endsWith("javelins") ||
                lower.endsWith("javelin(p)") || lower.endsWith("javelins(p)") ||
                lower.endsWith("javelin(p+)") || lower.endsWith("javelins(p+)") ||
                lower.endsWith("javelin(p++)") || lower.endsWith("javelins(p++)") ||
                lower.endsWith("javelin (p)") || lower.endsWith("javelins (p)") ||
                lower.endsWith("javelin (p+)") || lower.endsWith("javelins (p+)") ||
                lower.endsWith("javelin (p++)") || lower.endsWith("javelins (p++)"))
        {
            return false;
        }

        if (lower.endsWith(" knife") || lower.endsWith(" knife(p)") ||
                lower.endsWith(" knife(p+)") || lower.endsWith(" knife(p++)") ||
                lower.endsWith(" knife (p)") || lower.endsWith(" knife (p+)") ||
                lower.endsWith(" knife (p++)"))
        {
            return false;
        }

        if (lower.endsWith("thrownaxe"))
        {
            return false;
        }

        for (String tar : BLOCKED_TARS)
        {
            if (lower.equals(tar))
            {
                return false;
            }
        }

        for (String blocked : BLOCKED_WIELDABLE)
        {
            if (lower.equals(blocked))
            {
                return false;
            }
        }

        return false;
    }

    public static boolean isEquipmentByComposition(ItemComposition comp)
    {
        String[] actions = comp.getInventoryActions();
        if (actions == null)
        {
            return false;
        }
        for (String action : actions)
        {
            if (action == null) continue;
            if (action.equals("Wear") || action.equals("Wield") || action.equals("Equip"))
            {
                return true;
            }
        }
        return false;
    }
}

