package com.example;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("resourceman")
public interface ResourcemanConfig extends Config
{
	@ConfigSection(
			name = "Rules",
			description = "Settings for what is blocked",
			position = 0
	)
	String enforcementSection = "enforcement";

	@ConfigSection(
			name = "Notifications",
			description = "Settings for sounds and messages",
			position = 1
	)
	String notificationsSection = "notifications";

	@ConfigSection(
			name = "Appearance",
			description = "Settings for the plugin appearance",
			position = 2
	)
	String appearanceSection = "appearance";

	@ConfigItem(
			keyName = "blockShops",
			name = "Block NPC Shops",
			description = "Prevent buying from NPC shops",
			section = enforcementSection,
			position = 0
	)
	default boolean blockShops()
	{
		return true;
	}

	@ConfigItem(
			keyName = "blockImbuedHeart",
			name = "Block Imbued Heart",
			description = "Block trading or buying the Imbued Heart",
			section = enforcementSection,
			position = 1
	)
	default boolean blockImbuedHeart()
	{
		return false;
	}

	@ConfigItem(
			keyName = "playSound",
			name = "Play Sound on Blocked Action",
			description = "Play the error sound when a blocked action is attempted",
			section = notificationsSection,
			position = 0
	)
	default boolean playSound()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showChatMessage",
			name = "Show Chat Message on Blocked Action",
			description = "Send a chat message when a blocked action is attempted",
			section = notificationsSection,
			position = 1
	)
	default boolean showChatMessage()
	{
		return true;
	}

	@ConfigItem(
			keyName = "pluginIcon",
			name = "Plugin Icon",
			description = "Choose the icon shown in the sidebar",
			section = appearanceSection,
			position = 0
	)
	default ResourcemanIcon pluginIcon()
	{
		return ResourcemanIcon.RUNE_PICKAXE;
	}
}

