package com.example;

import com.example.data.StreakTracker;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class ResourcemanPanel extends PluginPanel
{
    private final ResourcemanPlugin plugin;

    private JLabel currentStreakLabel;
    private JLabel longestStreakLabel;
    private JLabel disableCountLabel;

    private Timer updateTimer;

    public ResourcemanPanel(ResourcemanPlugin plugin)
    {
        this.plugin = plugin;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        build();
    }

    private void build()
    {
        JLabel title = new JLabel("Resourceman Mode");
        title.setForeground(Color.WHITE);
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setHorizontalAlignment(SwingConstants.CENTER);
        title.setBorder(BorderFactory.createEmptyBorder(8, 0, 8, 0));
        add(title, BorderLayout.NORTH);

        JPanel statsPanel = new JPanel(new GridLayout(3, 1, 0, 8));
        statsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        statsPanel.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));

        // Current streak
        JPanel currentPanel = buildStatPanel("Current Streak", "0s");
        currentStreakLabel = (JLabel) ((JPanel) currentPanel.getComponent(1)).getComponent(0);
        statsPanel.add(currentPanel);

        // Longest streak
        JPanel longestPanel = buildStatPanel("Longest Streak", "0s");
        longestStreakLabel = (JLabel) ((JPanel) longestPanel.getComponent(1)).getComponent(0);
        statsPanel.add(longestPanel);

        // Times disabled
        JPanel disablePanel = buildStatPanel("Times Disabled", "0");
        disableCountLabel = (JLabel) ((JPanel) disablePanel.getComponent(1)).getComponent(0);
        statsPanel.add(disablePanel);

        add(statsPanel, BorderLayout.CENTER);

        JLabel note = new JLabel("<html><center><i>Disable count cannot be reset</i></center></html>");
        note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        note.setFont(FontManager.getRunescapeSmallFont());
        note.setHorizontalAlignment(SwingConstants.CENTER);
        note.setBorder(BorderFactory.createEmptyBorder(0, 8, 8, 8));
        add(note, BorderLayout.SOUTH);

        // Update current streak every second
        updateTimer = new Timer(1000, e -> update());
        updateTimer.start();
    }

    private JPanel buildStatPanel(String labelText, String valueText)
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));

        JLabel label = new JLabel(labelText);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(FontManager.getRunescapeSmallFont());

        JPanel valuePanel = new JPanel(new BorderLayout());
        valuePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JLabel value = new JLabel(valueText);
        value.setForeground(Color.WHITE);
        value.setFont(FontManager.getRunescapeBoldFont());

        valuePanel.add(value, BorderLayout.WEST);

        panel.add(label, BorderLayout.NORTH);
        panel.add(valuePanel, BorderLayout.CENTER);

        return panel;
    }

    public void update()
    {
        SwingUtilities.invokeLater(() ->
        {
            StreakTracker tracker = plugin.getStreakTracker();
            if (tracker == null)
            {
                return;
            }

            currentStreakLabel.setText(tracker.formatDuration(tracker.getCurrentStreakMs()));
            longestStreakLabel.setText(tracker.formatDuration(tracker.getLongestStreakMs()));
            disableCountLabel.setText(String.valueOf(tracker.getDisableCount()));
        });
    }

    public void stopTimer()
    {
        if (updateTimer != null)
        {
            updateTimer.stop();
        }
    }
}

package com.example;

import com.example.data.StreakTracker;
import com.example.listeners.GrandExchangeListener;
import com.example.listeners.GroundItemListener;
import com.example.listeners.ShopListener;
import com.example.listeners.SkillResourceListener;
import com.example.listeners.TradeListener;
import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

@Slf4j
@PluginDescriptor(
		name = "Resourceman Mode",
		description = "Enforces self-obtained resources only"
)
public class ResourcemanPlugin extends Plugin
{
	public static final String VIOLATION_MESSAGE = "Resourcemen gather their own resources";
	public static final int VIOLATION_SOUND = 2277;
	private static final long VIOLATION_COOLDOWN_MS = 3000;

	@Inject
	private Client client;

	@Inject
	private ResourcemanConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private GrandExchangeListener grandExchangeListener;

	@Inject
	private TradeListener tradeListener;

	@Inject
	private GroundItemListener groundItemListener;

	@Inject
	private ShopListener shopListener;

	@Inject
	private SkillResourceListener skillResourceListener;

	private StreakTracker streakTracker;
	private ResourcemanPanel panel;
	private NavigationButton navButton;
	private long lastViolationTime = 0;

	public StreakTracker getStreakTracker()
	{
		return streakTracker;
	}

	public ResourcemanPanel getPanel()
	{
		return panel;
	}

	public ItemManager getItemManager()
	{
		return itemManager;
	}

	private BufferedImage buildIcon()
	{
		try
		{
			int itemId = config.pluginIcon().getItemId();
			BufferedImage image = itemManager.getImage(itemId);
			if (image != null)
			{
				return image;
			}
		}
		catch (Exception e)
		{
			log.debug("Failed to load icon", e);
		}
		return buildFallbackIcon();
	}

	private BufferedImage buildFallbackIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(new Color(180, 120, 40));
		g.fillRect(0, 0, 16, 16);
		g.setColor(Color.WHITE);
		g.drawString("R", 3, 12);
		g.dispose();
		return image;
	}

	private void updateIcon()
	{
		clientThread.invokeLater(() ->
		{
			BufferedImage icon = buildIcon();
			SwingUtilities.invokeLater(() ->
			{
				if (navButton == null)
				{
					return;
				}
				clientToolbar.removeNavigation(navButton);
				navButton = NavigationButton.builder()
						.tooltip("Resourceman Mode")
						.icon(icon)
						.priority(5)
						.panel(panel)
						.build();
				clientToolbar.addNavigation(navButton);
			});
		});
	}

	@Override
	protected void startUp() throws Exception
	{
		streakTracker = new StreakTracker(configManager);

		panel = new ResourcemanPanel(this);
		panel.update();

		navButton = NavigationButton.builder()
				.tooltip("Resourceman Mode")
				.icon(buildFallbackIcon())
				.priority(5)
				.panel(panel)
				.build();

		clientToolbar.addNavigation(navButton);

		eventBus.register(grandExchangeListener);
		eventBus.register(tradeListener);
		eventBus.register(groundItemListener);
		eventBus.register(shopListener);
		eventBus.register(skillResourceListener);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			updateIcon();
		}

		log.debug("Resourceman Mode started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		// Record the disable
		if (streakTracker != null)
		{
			streakTracker.onPluginDisabled();
		}

		panel.stopTimer();
		clientToolbar.removeNavigation(navButton);
		eventBus.unregister(grandExchangeListener);
		eventBus.unregister(tradeListener);
		eventBus.unregister(groundItemListener);
		eventBus.unregister(shopListener);
		eventBus.unregister(skillResourceListener);
		skillResourceListener.reset();
		log.debug("Resourceman Mode stopped!");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			updateIcon();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals("resourceman") && event.getKey().equals("pluginIcon"))
		{
			updateIcon();
		}
	}

	public void triggerViolation()
	{
		long now = System.currentTimeMillis();
		if (now - lastViolationTime < VIOLATION_COOLDOWN_MS)
		{
			return;
		}
		lastViolationTime = now;

		if (config.showChatMessage())
		{
			chatMessageManager.queue(QueuedMessage.builder()
					.type(ChatMessageType.GAMEMESSAGE)
					.runeLiteFormattedMessage("<col=ff0000>" + VIOLATION_MESSAGE + "</col>")
					.build());
		}

		if (config.playSound())
		{
			client.playSoundEffect(VIOLATION_SOUND);
		}
	}

	@Provides
	ResourcemanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ResourcemanConfig.class);
	}
}

package com.example;

import java.util.HashSet;
import java.util.Set;

public class Whitelist
{
    private static final Set<String> ALLOWED_ITEMS = new HashSet<>();

    static
    {
        // Currency always allowed
        ALLOWED_ITEMS.add("coins");
        ALLOWED_ITEMS.add("platinum token");

        // Upgrade items always allowed
        ALLOWED_ITEMS.add("avernic defender hilt");

        // ─── AMMUNITION SLOT (Blessings only) ──────────────────
        ALLOWED_ITEMS.add("holy blessing");
        ALLOWED_ITEMS.add("peaceful blessing");
        ALLOWED_ITEMS.add("unholy blessing");
        ALLOWED_ITEMS.add("honourable blessing");
        ALLOWED_ITEMS.add("war blessing");
        ALLOWED_ITEMS.add("ancient blessing");
        ALLOWED_ITEMS.add("rada's blessing 1");
        ALLOWED_ITEMS.add("rada's blessing 2");
        ALLOWED_ITEMS.add("rada's blessing 3");
        ALLOWED_ITEMS.add("rada's blessing 4");
        ALLOWED_ITEMS.add("ghommal's lucky penny");
        ALLOWED_ITEMS.add("terrifying charm");
        ALLOWED_ITEMS.add("hallowed grapple");
        ALLOWED_ITEMS.add("mith grapple");
    }

    public static boolean isWhitelisted(String itemName)
    {
        if (itemName == null)
        {
            return false;
        }
        return ALLOWED_ITEMS.contains(itemName.toLowerCase());
    }

    public static boolean isDart(String itemName)
    {
        if (itemName == null)
        {
            return false;
        }
        String name = itemName.toLowerCase();
        return name.endsWith(" dart") || name.endsWith(" dart(p)") ||
                name.endsWith(" dart(p+)") || name.endsWith(" dart(p++)") ||
                name.endsWith(" dart (p)") || name.endsWith(" dart (p+)") ||
                name.endsWith(" dart (p++)");
    }

    public static void addItem(String itemName)
    {
        if (itemName != null && !itemName.isEmpty())
        {
            ALLOWED_ITEMS.add(itemName.toLowerCase());
        }
    }

    public static void removeItem(String itemName)
    {
        if (itemName != null)
        {
