package com.example.data;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.client.config.ConfigManager;

public class ResourceTracker
{
    private static final String CONFIG_GROUP = "resourceman";
    private static final String RESOURCES_KEY = "trackedResources";

    private final ConfigManager configManager;

    private Map<String, Integer> allTimeResources = new HashMap<>();
    private Map<String, Integer> sessionResources = new HashMap<>();

    public ResourceTracker(ConfigManager configManager)
    {
        this.configManager = configManager;
        load();
    }

    public void trackResource(String itemName, int quantity)
    {
        if (itemName == null || itemName.isEmpty())
        {
            return;
        }

        String name = itemName.toLowerCase();
        allTimeResources.merge(name, quantity, Integer::sum);
        sessionResources.merge(name, quantity, Integer::sum);
        save();
    }

    public Map<String, Integer> getAllTimeResources()
    {
        return allTimeResources.entrySet().stream()
                .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        Map.Entry::getValue,
                        (e1, e2) -> e1,
                        LinkedHashMap::new
                ));
    }

    public Map<String, Integer> getSessionResources()
    {
        return sessionResources.entrySet().stream()
                .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        Map.Entry::getValue,
                        (e1, e2) -> e1,
                        LinkedHashMap::new
                ));
    }

    public int getAllTimeResourceCount()
    {
        return allTimeResources.values().stream().mapToInt(Integer::intValue).sum();
    }

    public int getSessionResourceCount()
    {
        return sessionResources.values().stream().mapToInt(Integer::intValue).sum();
    }

    private void save()
    {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Integer> entry : allTimeResources.entrySet())
        {
            if (sb.length() > 0) sb.append(",");
            sb.append(entry.getKey()).append(":").append(entry.getValue());
        }
        configManager.setConfiguration(CONFIG_GROUP, RESOURCES_KEY, sb.toString());
    }

    private void load()
    {
        String resourceData = configManager.getConfiguration(CONFIG_GROUP, RESOURCES_KEY);
        if (resourceData != null && !resourceData.isEmpty())
        {
            for (String entry : resourceData.split(","))
            {
                String[] parts = entry.split(":");
                if (parts.length == 2)
                {
                    try
                    {
                        allTimeResources.put(parts[0], Integer.parseInt(parts[1]));
                    }
                    catch (NumberFormatException e)
                    {
                        // Skip
                    }
                }
            }
        }
    }

    public void resetSession()
    {
        sessionResources.clear();
    }
}

package com.example.data;

import net.runelite.client.config.ConfigManager;

public class StreakTracker
{
    private static final String CONFIG_GROUP = "resourceman";
    private static final String STREAK_START_KEY = "streakStart";
    private static final String LONGEST_STREAK_KEY = "longestStreak";
    private static final String DISABLE_COUNT_KEY = "disableCount";

    private final ConfigManager configManager;

    private long streakStart;
    private long longestStreakMs;
    private int disableCount;

    public StreakTracker(ConfigManager configManager)
    {
        this.configManager = configManager;
        load();
    }

    private void load()
    {
        String streakStartStr = configManager.getConfiguration(CONFIG_GROUP, STREAK_START_KEY);
        String longestStr = configManager.getConfiguration(CONFIG_GROUP, LONGEST_STREAK_KEY);
        String disableStr = configManager.getConfiguration(CONFIG_GROUP, DISABLE_COUNT_KEY);

        streakStart = streakStartStr != null ? Long.parseLong(streakStartStr) : System.currentTimeMillis();
        longestStreakMs = longestStr != null ? Long.parseLong(longestStr) : 0;
        disableCount = disableStr != null ? Integer.parseInt(disableStr) : 0;

        // If no streak start saved, save it now
        if (streakStartStr == null)
        {
            configManager.setConfiguration(CONFIG_GROUP, STREAK_START_KEY, String.valueOf(streakStart));
        }
    }

    public void onPluginDisabled()
    {
        // Update longest streak if current is longer
        long currentStreakMs = getCurrentStreakMs();
        if (currentStreakMs > longestStreakMs)
        {
            longestStreakMs = currentStreakMs;
            configManager.setConfiguration(CONFIG_GROUP, LONGEST_STREAK_KEY, String.valueOf(longestStreakMs));
        }

        // Increment disable count
        disableCount++;
        configManager.setConfiguration(CONFIG_GROUP, DISABLE_COUNT_KEY, String.valueOf(disableCount));

        // Reset streak start
        streakStart = System.currentTimeMillis();
        configManager.setConfiguration(CONFIG_GROUP, STREAK_START_KEY, String.valueOf(streakStart));
    }

    public long getCurrentStreakMs()
    {
        return System.currentTimeMillis() - streakStart;
    }

    public long getLongestStreakMs()
    {
        return longestStreakMs;
    }

    public int getDisableCount()
    {
        return disableCount;
    }

    public String formatDuration(long ms)
    {
        long seconds = ms / 1000;
        long minutes = seconds / 60;
        long hours = minutes / 60;
        long days = hours / 24;

        if (days > 0)
        {
            return days + "d " + (hours % 24) + "h " + (minutes % 60) + "m";
        }
        else if (hours > 0)
        {
            return hours + "h " + (minutes % 60) + "m";
        }
        else if (minutes > 0)
        {
            return minutes + "m " + (seconds % 60) + "s";
        }
        else
        {
            return seconds + "s";
        }
    }
}

