package com.example.listeners;

import com.example.ItemRules;
import com.example.ResourcemanPlugin;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import java.util.HashMap;
import java.util.Map;

public class SkillResourceListener
{
    private static final int COINS_ID = 995;
    private static final int PLATINUM_TOKEN_ID = 13204;
    private static final int BANK_GROUP_ID = 12;

    @Inject
    private Client client;

    @Inject
    private ResourcemanPlugin plugin;

    @Inject
    private ItemManager itemManager;

    private Map<Integer, Integer> previousInventory = new HashMap<>();
    private Map<Integer, Integer> droppedItems = new HashMap<>();
    private boolean initialized = false;
    private boolean bankOpen = false;

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == BANK_GROUP_ID)
        {
            bankOpen = true;
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (event.getGroupId() == BANK_GROUP_ID)
        {
            bankOpen = false;
            ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
            if (inventory != null)
            {
                Map<Integer, Integer> current = new HashMap<>();
                for (Item item : inventory.getItems())
                {
                    if (item.getId() != -1)
                    {
                        current.merge(item.getId(), item.getQuantity(), Integer::sum);
                    }
                }
                previousInventory = current;
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        String option = event.getMenuOption();
        if (!option.equals("Drop"))
        {
            return;
        }

        int itemId = event.getItemId();
        if (itemId == -1)
        {
            return;
        }

        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null)
        {
            return;
        }

        int slotIndex = event.getParam0();
        Item[] items = inventory.getItems();
        if (slotIndex >= 0 && slotIndex < items.length)
        {
            int qty = items[slotIndex].getQuantity();
            droppedItems.merge(itemId, qty, Integer::sum);
        }
        else
        {
            droppedItems.merge(itemId, 1, Integer::sum);
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INVENTORY.getId())
        {
            return;
        }

        ItemContainer container = event.getItemContainer();
        if (container == null)
        {
            return;
        }

        Map<Integer, Integer> currentInventory = new HashMap<>();
        for (Item item : container.getItems())
        {
            if (item.getId() == -1)
            {
                continue;
            }
            currentInventory.merge(item.getId(), item.getQuantity(), Integer::sum);
        }

        if (!initialized)
        {
            previousInventory = currentInventory;
            initialized = true;
            return;
        }

        if (bankOpen)
        {
            previousInventory = currentInventory;
            return;
        }

        previousInventory = currentInventory;
    }

    public void reset()
    {
        previousInventory.clear();
        droppedItems.clear();
        initialized = false;
        bankOpen = false;
    }
}

package com.example.listeners;

import com.example.ItemRules;
import com.example.ResourcemanConfig;
import com.example.ResourcemanPlugin;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

public class TradeListener
{
    private static final int[] TRADE_GROUPS = {334, 335};

    @Inject
    private Client client;

    @Inject
    private ResourcemanPlugin plugin;

    @Inject
    private ResourcemanConfig config;

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!event.getMenuOption().equals("Accept"))
        {
            return;
        }

        int groupId = event.getParam1() >> 16;
        boolean isTrade = false;
        for (int g : TRADE_GROUPS)
        {
            if (groupId == g)
            {
                isTrade = true;
                break;
            }
        }

        if (!isTrade)
        {
            return;
        }

        if (hasViolation())
        {
            event.consume();
            plugin.triggerViolation();
        }
    }

    private boolean hasViolation()
    {
        for (int groupId : TRADE_GROUPS)
        {
            for (int child = 0; child < 60; child++)
            {
                Widget w = client.getWidget(groupId, child);
                if (w == null)
                {
                    continue;
                }

                Widget[] dynamics = w.getDynamicChildren();
                if (dynamics != null)
                {
                    for (Widget d : dynamics)
                    {
                        if (d != null && d.getItemId() != -1 && isViolationItem(d.getItemId()))
                        {
                            return true;
                        }
                    }
                }

                if (w.getItemId() != -1 && isViolationItem(w.getItemId()))
                {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isViolationItem(int itemId)
    {
        ItemComposition itemComp = client.getItemDefinition(itemId);

        if (!itemComp.isTradeable())
        {
            return false;
        }

        String itemName = itemComp.getName();
        return !ItemRules.isAllowedItem(itemName, itemComp, config.blockImbuedHeart());
    }
}

